using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Changes pause state of a file in the file download list
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> ToggleDownloadIsPausedAsync(int fileId = default, bool isPaused = default)
    {

           using var activity =  StartCallActivity("ToggleDownloadIsPausedAsync", typeof(ToggleDownloadIsPaused).FullName ?? "ToggleDownloadIsPausedAsync");

           try
           {
             return client.ToggleDownloadIsPausedAsync(fileId, isPaused);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
